## Test code

### C++ — `tests/core/object/test_bench_refcount.cpp`

Run with `bin/godot.macos.editor.arm64 --headless --test --test-case="*RCBench*"`.

```cpp
/**************************************************************************/
/*  test_bench_refcount.cpp                                               */
/**************************************************************************/
/* Temporary benchmark file — not intended for upstream.                  */
/* Run with: bin/godot.* --headless --test --test-case="*RCBench*"        */
/**************************************************************************/

#include "core/io/resource.h"
#include "core/object/class_db.h"
#include "core/object/object.h"
#include "core/object/ref_counted.h"
#include "core/variant/variant.h"
#include "scene/main/node.h"

#include "tests/test_macros.h"

TEST_FORCE_LINK(test_bench_refcount)

#include <algorithm>
#include <chrono>
#include <cstdio>
#include <vector>

namespace TestBenchRefCount {

// Keeps the optimizer from discarding the results.
static uint64_t g_sink = 0;

template <typename F>
static void bench(const char *p_name, int64_t p_ops, F p_f) {
	constexpr int REPS = 11;
	std::vector<double> samples;
	// First iteration is warmup and discarded.
	for (int i = 0; i < REPS + 1; i++) {
		const auto t0 = std::chrono::steady_clock::now();
		p_f();
		const auto t1 = std::chrono::steady_clock::now();
		if (i > 0) {
			samples.push_back(std::chrono::duration<double>(t1 - t0).count());
		}
	}
	std::sort(samples.begin(), samples.end());
	const double median = samples[samples.size() / 2];
	const double best = samples.front();
	printf("BENCH|%-40s|%10.2f|%10.2f\n",
			p_name, median * 1e9 / double(p_ops), best * 1e9 / double(p_ops));
	fflush(stdout);
}

// ---------------------------------------------------------------- changed --

TEST_CASE("[RCBench] creation") {
	static constexpr int N = 1'000'000;

	bench("memnew(RefCounted)", N, []() {
		for (int i = 0; i < N; i++) {
			Ref<RefCounted> r = memnew(RefCounted);
			g_sink += uint64_t(r.ptr() != nullptr);
		}
	});

	bench("memnew(Resource)", N, []() {
		for (int i = 0; i < N; i++) {
			Ref<Resource> r = memnew(Resource);
			g_sink += uint64_t(r.ptr() != nullptr);
		}
	});

	bench("Ref<Resource>::instantiate()", N, []() {
		for (int i = 0; i < N; i++) {
			Ref<Resource> r;
			r.instantiate();
			g_sink += uint64_t(r.ptr() != nullptr);
		}
	});

	const StringName rc_name("RefCounted");
	bench("ClassDB::instantiate(RefCounted)+Ref", N, [&]() {
		for (int i = 0; i < N; i++) {
			Ref<RefCounted> r = Object::cast_to<RefCounted>(ClassDB::instantiate(rc_name));
			g_sink += uint64_t(r.ptr() != nullptr);
		}
	});

	const StringName res_name("Resource");
	bench("ClassDB::instantiate(Resource)+Ref", N, [&]() {
		for (int i = 0; i < N; i++) {
			Ref<Resource> r = Object::cast_to<Resource>(ClassDB::instantiate(res_name));
			g_sink += uint64_t(r.ptr() != nullptr);
		}
	});

	Ref<Resource> proto;
	proto.instantiate();
	bench("Resource::duplicate()", N / 10, [&]() {
		for (int i = 0; i < N / 10; i++) {
			Ref<Resource> d = proto->duplicate();
			g_sink += uint64_t(d.ptr() != nullptr);
		}
	});
}

// --------------------------------------------------------------- controls --

TEST_CASE("[RCBench] controls") {
	static constexpr int N = 1'000'000;

	// Plain Object: not RefCounted, must be untouched.
	bench("memnew(Node)+memdelete", N, []() {
		for (int i = 0; i < N; i++) {
			Node *n = memnew(Node);
			g_sink += uint64_t(n != nullptr);
			memdelete(n);
		}
	});

	const StringName node_name("Node");
	bench("ClassDB::instantiate(Node)+memdelete", N, [&]() {
		for (int i = 0; i < N; i++) {
			Object *o = ClassDB::instantiate(node_name);
			g_sink += uint64_t(o != nullptr);
			memdelete(o);
		}
	});

	// Steady-state refcounting: reference()/unreference() only.
	Ref<Resource> held;
	held.instantiate();
	bench("Ref copy+destroy", N, [&]() {
		for (int i = 0; i < N; i++) {
			Ref<Resource> copy = held;
			g_sink += uint64_t(copy.ptr() != nullptr);
		}
	});

	bench("Variant from Ref", N, [&]() {
		for (int i = 0; i < N; i++) {
			Variant v = held;
			g_sink += uint64_t(v.get_type());
		}
	});

	// Goes through RefCounted::init_ref().
	Object *raw = held.ptr();
	bench("Variant from Object*", N, [&]() {
		for (int i = 0; i < N; i++) {
			Variant v = raw;
			g_sink += uint64_t(v.get_type());
		}
	});

	// Refcounted containers this commit does not touch.
	bench("Array()", N, []() {
		for (int i = 0; i < N; i++) {
			Array a;
			g_sink += uint64_t(a.is_empty());
		}
	});

	bench("Dictionary()", N, []() {
		for (int i = 0; i < N; i++) {
			Dictionary d;
			g_sink += uint64_t(d.is_empty());
		}
	});

	bench("StringName(String)", N / 10, []() {
		for (int i = 0; i < N / 10; i++) {
			StringName sn(String("bench_name_") + itos(i & 1023));
			g_sink += uint64_t(sn.hash());
		}
	});
}

} // namespace TestBenchRefCount
```

### GDScript — `bench.gd`

Run with `bin/godot.macos.editor.arm64 --headless --path <project> -s bench.gd`,
in a project directory containing only `project.godot` and `bench.gd`.

```gdscript
extends SceneTree

const REPS := 11
const N := 300000

var sink := 0

class Custom extends RefCounted:
	var x := 0

class CustomRes extends Resource:
	var x := 0

func _bench(bench_name: String, ops: int, f: Callable) -> void:
	var samples: Array = []
	# First iteration is warmup and discarded.
	for i in REPS + 1:
		var t0 := Time.get_ticks_usec()
		f.call()
		var t1 := Time.get_ticks_usec()
		if i > 0:
			samples.append(float(t1 - t0))
	samples.sort()
	var median: float = samples[samples.size() / 2]
	var best: float = samples[0]
	# usec for `ops` operations -> ns per operation.
	print("BENCH|%-40s|%10.2f|%10.2f" % [bench_name, median * 1000.0 / ops, best * 1000.0 / ops])

func _initialize() -> void:
	var held := Resource.new()

	# ---- creation paths affected by the change ----
	_bench("RefCounted.new()", N, func():
		for i in N:
			var r := RefCounted.new()
			sink += 1 if r != null else 0)

	_bench("Resource.new()", N, func():
		for i in N:
			var r := Resource.new()
			sink += 1 if r != null else 0)

	_bench("ClassDB.instantiate(RefCounted)", N, func():
		for i in N:
			var r = ClassDB.instantiate("RefCounted")
			sink += 1 if r != null else 0)

	_bench("script class .new() (RefCounted)", N, func():
		for i in N:
			var r := Custom.new()
			sink += 1 if r != null else 0)

	_bench("script class .new() (Resource)", N, func():
		for i in N:
			var r := CustomRes.new()
			sink += 1 if r != null else 0)

	_bench("Resource.duplicate()", N / 10, func():
		for i in N / 10:
			var d := held.duplicate()
			sink += 1 if d != null else 0)

	# ---- controls ----
	_bench("Node.new()+free()", N, func():
		for i in N:
			var n := Node.new()
			sink += 1 if n != null else 0
			n.free())

	_bench("Ref copy (var assign)", N, func():
		for i in N:
			var r := held
			sink += 1 if r != null else 0)

	_bench("Ref pass to function", N, func():
		for i in N:
			sink += _take(held))

	_bench("Array append+clear (Ref)", N, func():
		var a: Array = []
		for i in N:
			a.append(held)
			a.clear()
			sink += 1)

	_bench("Array()", N, func():
		for i in N:
			var a: Array = []
			sink += 1 if a.is_empty() else 0)

	_bench("Dictionary()", N, func():
		for i in N:
			var d: Dictionary = {}
			sink += 1 if d.is_empty() else 0)

	print("sink=", sink)
	quit()

func _take(r: Resource) -> int:
	return 1 if r != null else 0
```
